# owner: platform
"""Weekly timesheet lines, one per worker."""

from typing import Iterable, List

from hourglass.models import Shift


# ---
def weekly_timesheet(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, busiest first, like
    Brisa: 3 shifts, 9.0 hours. ValueError when there are no
    shifts or a shift has a blank worker name."""
    totals = _totals(shifts)
    ranked = sorted(totals.items(), key=_rank)
    return [_line(name, *stats) for name, stats in ranked]


def _totals(shifts: Iterable[Shift]) -> dict:
    totals = {}
    for shift in shifts:
        _add(totals, shift)
    if not totals:
        raise ValueError("no shifts to total")
    return totals


def _add(totals: dict, shift: Shift) -> None:
    name = shift.worker.strip()
    if not name:
        raise ValueError("shift has a blank worker name")
    entry = totals.setdefault(name, [0, 0])
    entry[0] += 1
    entry[1] += shift.span.minutes


def _rank(item: tuple) -> tuple:
    name, (count, mins) = item
    return (-mins, -count, name)


def _line(name: str, count: int, mins: int) -> str:
    noun = "shift" if count == 1 else "shifts"
    return f"{name}: {count} {noun}, {mins / 60:.1f} hours"
